T.RUTINLER = [{"tip":"cember","yon":"yatay","adim":[["Bakış açıları","Bu konuya kimler farklı açıdan bakar? Hepsini çemberin çevresine yaz."],["Ben ... gözüyle düşünüyorum","Bir bakış açısı seç. O kişi ya da şey olsaydın konuyu nasıl görürdün?"],["Sanırım ...","O bakış açısından konuyu anlat. Onun yerine geç, onun gibi konuş."],["Bu açıdan bir sorum var","Seçtiğin bakış açısından bir soru sor."]],"amac":"Birden çok bakış açısını görmeyi ve aynı şeye farklı insanların farklı bağlarla baktığını anlamayı sağlar.","ne":"Karmaşık konular, ikilemler, sanat eserleri; öğrenciler bir konuyu yalnızca iki taraflı gördüğünde.","id":"bakis-acilari-cemberi","ad":"Bakış Açıları Çemberi","kat":["Temel Düşünme Rutinleri","Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"kolon","yon":"yatay","adim":[["İddia","Bu konu hakkında ne söyleyebilirim? Bir açıklama ya da yorum yaz."],["Destek","Bunu neden söylüyorum? Gördüğüm, bildiğim, hissettiğim kanıtlar neler?"],["Soru","İddiamla ilgili hâlâ neyi merak ediyorum? Açıklanmayan ne kaldı?"]],"amac":"İddia kurmayı ve onu kanıtla desteklemeyi öğretir; akıl yürütmenin süren bir süreç olduğunu gösterir.","ne":"Bir metin, deney sonucu, haber ya da sanat eseri üzerine konuşurken. Önce tüm sınıfla örnekleyin.","id":"iddia-destek-soru","ad":"İddia, Destek, Soru","kat":["Temel Düşünme Rutinleri","Fikirlerin Daha Derinlemesine İncelenmesi"]},{"tip":"pusula","yon":"dikey","adim":[["D: Heyecanlandıran","Bu fikirde seni heyecanlandıran ne? Artısı ne?"],["B: Endişelendiren","Bu fikirde seni endişelendiren ne? Eksisi ne?"],["K: Bilmem gereken","Karar vermek için başka neyi bilmem gerekiyor?"],["G: Görüşüm","Şimdi ne düşünüyorum? Nasıl ilerleyelim?"]],"amac":"Bir fikir ya da öneriyi karar vermeden önce her yönüyle incelemeyi sağlar.","ne":"Sınıf düzeni değişikliği, bir karakterin kararı, okul kuralı gibi bir öneri tartışılırken. Heyecan verici yönden başlamak kolaylaştırır.","id":"pusula","ad":"Pusula","kat":["Temel Düşünme Rutinleri","Fikirleri Tanıtma ve Keşfetme","Perspektif Alma"]},{"tip":"kolon","yon":"yatay","adim":[["Bağlan","Bu yeni bilgi, zaten bildiğim neyle bağlantılı?"],["Genişlet","Hangi yeni fikir düşüncemi büyüttü ya da başka yöne götürdü?"],["Meydan oku","Kafamı karıştıran, hâlâ zor gelen ne var?"]],"amac":"Yeni fikirleri bilinenlerle ilişkilendirmeyi ve öğrendiklerinin düşünceyi nasıl genişlettiğini fark etmeyi sağlar.","ne":"Okuma, video ya da yeni bilgi sunulan dersin sonunda; ünite kapanışında.","id":"baglan-genislet-meydan-oku","ad":"Bağlan, Genişlet, Meydan Oku","kat":["Temel Düşünme Rutinleri"]},{"tip":"oncesonra","yon":"yatay","adim":[["Eskiden düşünürdüm ki...","Bu konuya başlamadan önce ne düşünüyordum?"],["Şimdi düşünüyorum ki...","Öğrendiklerimden sonra şimdi ne düşünüyorum?"]],"amac":"Düşüncenin nasıl ve neden değiştiğini fark ettirir, yeni öğrenmeyi pekiştirir.","ne":"Okuma, film, gezi, tartışma ya da ünite sonunda; ilk düşüncelerin değişmiş olabileceği her an.","id":"eskiden-dusunurdum-simdi-dusunuyorum","ad":"Eskiden Düşünürdüm Şimdi Düşünüyorum","kat":["Temel Düşünme Rutinleri","Fikirleri Sentezleme ve Düzenleme","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"kolon","yon":"yatay","adim":[["Ne görüyorum?","Sadece gözüne görüneni söyle."],["Ne düşünüyorum?","Bu neden böyle olabilir? Neyi görünce bunu düşündün?"],["Neyi merak ediyorum?","Aklında hangi sorular kaldı?"]],"amac":"Dikkatli gözlem ve düşünceli yorum yapmayı teşvik eder, merak uyandırır ve sorgulamaya zemin hazırlar.","ne":"Ünite başında bir görsel, nesne, grafik ya da videoyla. Önce sessizce bireysel düşünme zamanı verin.","id":"gor-dusun-merak-et","ad":"Gör, Düşün, Merak Et","kat":["Temel Düşünme Rutinleri","Fikirleri Tanıtma ve Keşfetme","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"satir","yon":"dikey","adim":[["Düşün","Soruyu kendi başına sessizce düşün. İstersen yaz ya da çiz."],["Eşleş","Yanındaki arkadaşınla düşüncelerinizi sırayla anlatın, dikkatle dinleyin."],["Paylaş","Arkadaşının düşüncesini sınıfa anlat."]],"amac":"Akıl yürütmeyi ve açıklamayı, başkalarını dinleyerek birden çok bakış açısını anlamayı destekler.","ne":"Deneyden önce, problem çözerken, bir metin okuduktan sonra. Eşini anlatacağını önceden söylemek dinlemeyi artırır.","id":"dusun-esles-paylas","ad":"Düşün, Eşleş, Paylaş","kat":["Temel Düşünme Rutinleri","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"kolon","yon":"yatay","adim":[["Düşün","Bu konu hakkında ne bildiğimi düşünüyorum?"],["Sorgula","Hangi sorularım var? Neyi merak ediyorum?"],["Keşfet","Sorularımın cevabını nasıl bulabilirim?"]],"amac":"Ön bilgiyi harekete geçirir, merak uyandırır ve daha derin sorgulamaya hazırlar; mevcut anlayışı görmeyi sağlar.","ne":"Yeni konu ya da ünite başında. Yanlış kavramları da listeleyin, ünite içinde geri dönün.","id":"dusun-sorgula-kesfet","ad":"Düşün, Sorgula, Keşfet","kat":["Temel Düşünme Rutinleri","Fikirleri Tanıtma ve Keşfetme","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"satir","yon":"dikey","adim":[["Neler oluyor?","Burada ne oluyor sence?"],["Bunu söylemene ne neden oldu?","Neyi görünce bunu düşündün? Kanıtını göster."]],"amac":"Gözlemi, açıklama kurmayı ve kanıta dayalı akıl yürütmeyi geliştirir.","ne":"Görsel, sanat eseri, deney gözlemi, şiir. Tartışma akarken öğrenci yorum yaptığında soruyu ekleyin.","id":"bunu-soylemenize-neden-olan-nedir","ad":"Bunu Söylemenize Neden Olan Nedir?","kat":["Temel Düşünme Rutinleri","Fikirlerin Daha Derinlemesine İncelenmesi","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"kopru","yon":"yatay","adim":[["Öğrenmeden önce: 3 kelime","Konu deyince aklına gelen 3 kelime ya da fikir"],["Öğrenmeden önce: 2 soru","Konuyla ilgili 2 sorun"],["Öğrenmeden önce: 1 benzetme","Bu konu neye benziyor?"],["Öğrendikten sonra: 3 kelime","Şimdi aklına gelen 3 kelime ya da fikir"],["Öğrendikten sonra: 2 soru","Şimdi sorduğun 2 soru"],["Öğrendikten sonra: 1 benzetme","Şimdi bu konu neye benziyor?"],["Köprü","İlk düşüncelerin yenileriyle nasıl bağlantılı, ne değişti?"]],"amac":"Bir öğrenme deneyiminden önce ve sonra düşüncenin nasıl değiştiğini görmeyi sağlar.","ne":"Öğrencilerin az da olsa bildiği bir konuda. Önce bölümü hızlı yazılır; ilk düşüncelerin doğru ya da yanlış olmadığını söyleyin.","id":"3-2-1-kopru","ad":"3-2-1 Köprü","kat":["Fikirleri Tanıtma ve Keşfetme","Olasılıklar ve Benzetmeler Üretmek"]},{"tip":"merkez","yon":"yatay","adim":[["Fikirlerim","Bu soruyu düşününce aklıma hangi fikirler geliyor?"],["Bağlantılar","Arkadaşlarımın yazdıklarıyla hangi bağlantıları kurabilirim?"],["Sorularım","Hepsini okuyunca hangi sorular ortaya çıkıyor?"]],"amac":"Sessiz yazılı konuşmayla birlikte anlam kurmayı sağlar; konuşmaya çekinen öğrencilere de söz verir.","ne":"Ortaya soruyu yazın, kâğıtları masalara koyun. Gruplar 5 dakikada bir kâğıt değiştirir, en sonda ortak temaları konuşun. Konuşmak yok, yalnızca yazmak var.","id":"tebesir-konusmasi","ad":"Tebeşir Konuşması","kat":["Fikirleri Tanıtma ve Keşfetme"]},{"tip":"liste","yon":"dikey","adim":[["Soru üret","Konu hakkında en az 12 soru yaz. Şu başlangıçları dene: Neden...? Ya ... olsaydı? Amacı ne...? ... olsaydı ne değişirdi?"],["Seç","En ilginç soruları işaretle, tartışmak için birini seç."],["Düşün","Bu konuda daha önce aklına gelmeyen hangi yeni fikirlerin oldu?"]],"amac":"Düşünmeyi ve araştırmayı başlatan soru üretme pratiği sağlar; konunun derinliğini ve çok yönlülüğünü gösterir.","ne":"Yeni konu girişinde, ünite ortasında merakı tazelemek için, ünite sonunda daha karmaşık sorular sormak için.","id":"yaratici-soru-baslangici","ad":"Yaratıcı Soru Başlangıcı","kat":["Fikirleri Tanıtma ve Keşfetme","Fikirlerin Daha Derinlemesine İncelenmesi","Olasılıklar ve Benzetmeler Üretmek"]},{"tip":"izgara","yon":"yatay","adim":[["Daha iyi çalışsın","Bunu nasıl daha iyi çalışır hâle getirebiliriz?"],["Daha kolay kullanılsın","Bunu nasıl daha kolay ve hızlı kullanılır yaparız?"],["Herkes için daha iyi olsun","Nasıl daha adil, daha güvenli, paylaşması daha kolay olur?"],["Daha güzel olsun","Bunu nasıl daha güzel yapabiliriz?"]],"amac":"Bir nesne ya da sistemi yeniden tasarlamak için farklı ve odaklı düşünmeyi, fırsat görmeyi teşvik eder.","ne":"Sınıftaki ya da okuldaki bir nesne ya da düzen üzerinde. Küçük yaşta 'daha etik' yerine 'herkes için daha iyi' deyin; çizim ve canlandırma kabul edin.","id":"soyle-bir-dusun","ad":"Şöyle Bir Düşün","kat":["Fikirleri Tanıtma ve Keşfetme","Nesnelerin ve Sistemlerin Araştırılması"]},{"tip":"satir","yon":"dikey","adim":[["Bak","Esere yakından bak. Neler fark ediyorsun? Çok sayıda gözlem yap."],["Bir mercek seç ve paylaş","Dünyaya hangi gözle bakıyorsun (ailedeki rolün, yaşın, yaşadığın yer)? O gözle eseri anlat."],["Sor","Arkadaşının bakışını anlamak için soru sor: ... ile ne demek istediğini anlatır mısın?"],["Yansıt","Esere yeniden bak. Yeni neler fark ettin? Hangi konular aklına geldi?"]],"amac":"Bir esere farklı kimlik ve geçmiş merceklerinden bilinçli bakmayı, diyalog yoluyla başkasının bakışını anlamayı sağlar.","ne":"Birlikte yaşamla ilgili bir tema taşıyan sanat eseri ya da görselle; 10-20 dakika, eşli ya da küçük grup.","id":"diyalog-icin-mercekler","ad":"Diyalog İçin Mercekler","kat":["Fikirleri Tanıtma ve Keşfetme","Perspektif Alma","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"tablo","yon":"yatay","sutun":["Adlandır","Açıkla","Eylem"],"adim":[["Adlandır","Hatırladığın tüm parçaları say. İşaret edip adını söyleyebileceğin şeyler."],["Açıkla","Her birine bir sıfat ekle. Nasıl görünüyor?"],["Eylem","Her biri ne yapıyor? Bütüne nasıl katkı veriyor?"]],"amac":"Yakından bakmayı, betimleyici dili ve çalışma belleğini geliştirir.","ne":"Görseli 1-2 dakika sessizce izletin, sonra kaldırın; öğrenciler hatırladıklarını sayar. Her fiil bir kez kullanılır kuralı yaratıcılığı artırır.","id":"adlandirma-aciklama-eylem","ad":"Adlandırma, Açıklama, Eylem","kat":["Fikirleri Tanıtma ve Keşfetme"]},{"tip":"baglanti","yon":"yatay","adim":[["İlgi alanlarım","Hobilerimden ya da sevdiğim şeylerden bazıları"],["Okul konularım","Derslerimden ya da okulda öğrendiğim konulardan bazıları"],["Bağlantı","Bir ilgi alanınla bir konu arasına çizgi çek, çizginin üstüne bağlantıyı yaz."],["Keşfetmek için","Bu bağlantıyı daha çok araştırmak için neler yapabilirim?"]],"amac":"Okul dışındaki ilgi alanlarını okuldaki konulara bağlamayı ve bağlantı kurma alışkanlığı kazanmayı sağlar.","ne":"İlk bağlantılar yüzeysel görünse de olur; 'neler yapabilirim' adımında derinleşir. Bağlantı türü önerin: biçim, yapı, hikâye, kültür.","id":"disaridan-iceri","ad":"Dışarıdan İçeri","kat":["Fikirleri Tanıtma ve Keşfetme","Fikirlerin Daha Derinlemesine İncelenmesi"]},{"tip":"kolon","yon":"yatay","adim":[["Parçalar","Bunun parçaları neler? Çiz ya da listele."],["Bakış açıları","Kimler buna farklı açıdan bakar? Kullanan, yapan, etkilenen kim?"],["Ben","Benim bununla bağım ne? Onu nasıl görüyorum, neden?"]],"amac":"Ayrıntıya yakından bakmayı, farklı kullanıcı ve paydaşları düşünmeyi ve kendi bağlantısını fark etmeyi sağlar.","ne":"Çok parçalı nesneler ve sistemler (ulaşım, okul yemekhanesi). Her adıma ayrı zaman verin; mümkünse nesneyi söküp çizdirin.","id":"parcalar-perspektifler-ben","ad":"Parçalar, Perspektifler, Ben","kat":["Fikirleri Tanıtma ve Keşfetme","Nesnelerin ve Sistemlerin Araştırılması"]},{"tip":"kolon","yon":"yatay","adim":[["Parçalar","Bütün parçaları neler?"],["Amaçlar","Ne işe yarıyor? Her parça ne işe yarıyor?"],["Karmaşıklıklar","Parçalar birlikte nasıl çalışıyor? Bir parça eksik olsaydı ne olurdu?"]],"amac":"Yavaşlayıp ayrıntılı gözlem yapmayı, nesnenin ya da sistemin görünen yüzünün ötesine bakmayı ve merak etmeyi sağlar.","ne":"Sınıfta dokunulabilen bir nesneyle başlayın. Küçük yaşta 'karmaşıklık' yerine 'bulmaca' deyin, tek bir ortak çizelge yapın.","id":"parcalar-amaclar-karmasikliklar","ad":"Parçalar, Amaçlar, Karmaşıklıklar","kat":["Fikirleri Tanıtma ve Keşfetme","Nesnelerin ve Sistemlerin Araştırılması","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"meyve","yon":"dikey","adim":[["Kabuk: yüzeyi tanı","Ne görüyoruz? Ne biliyoruz?"],["Kabuğun altı: gizemleri ara","Bizi şaşırtan, merak ettiğimiz ne?"],["Meyve: anlamı kur","Bağlantılar kuralım, açıklayalım, farklı açılardan bakalım."],["Çekirdek: özü yakala","Bu konunun en önemli fikri ne?"]],"amac":"Karmaşık bir konuyu günler ya da haftalar boyunca anlamayı planlamak ve izlemek için bir haritadır.","ne":"Ünite boyunca duvarda kalsın. Kabuktan başlayın, sırayla değil ihtiyaca göre ilerleyin; öğrenciler yapışkan notlarla ekleme yapsın.","id":"meyveyi-soy","ad":"Meyveyi Soy","kat":["Fikirleri Tanıtma ve Keşfetme","Fikirlerin Daha Derinlemesine İncelenmesi"]},{"tip":"izgara","yon":"yatay","adim":[["Gör","Ne görüyorsun? Yorum yapmadan sadece anlat."],["Düşün","Burada neler oluyor? Bu ne anlama geliyor olabilir?"],["Ben","Bu eser bana kendi hayatımdan neyi hatırlatıyor?"],["Biz","Bu, insanların hangi ortak hikâyesine bağlanıyor?"]],"amac":"Bir eserden yola çıkarak kişisel bağlar kurmayı ve bunları daha büyük insan deneyimine bağlamayı sağlar.","ne":"Sanat eseri ya da görselle. Ben adımında güvenli ortam önemli; önce siz örnek verin, büyük grupta ikili ya da üçlü çalışın.","id":"gor-dusun-ben-biz","ad":"Gör, Düşün, Ben, Biz","kat":["Fikirleri Tanıtma ve Keşfetme","Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"satir","yon":"dikey","adim":[["İçeri adım at","Bu kişi ne hissediyor, neye inanıyor, ne biliyor olabilir?"],["Dışarı adım at","Onu daha iyi anlamak için neyi öğrenmem gerekiyor?"],["Geri adım at","Kendi bakışım hakkında ne fark ettim? Başkasının yerine geçmek neden zor?"]],"amac":"Başkasının bakış açısını sorumlulukla almayı ve bunun kendimizi de anlamak olduğunu fark etmeyi besler.","ne":"Bir hikâye karakteri, tarihî olay, haber ya da ekosistemdeki bir canlı için. İlk izlenimlerin yanılabileceğini normalleştirin.","id":"iceri-adim-at-disari-adim-at-geri-adim-at","ad":"İçeri Adım At, Dışarı Adım At, Geri Adım At","kat":["Fikirleri Tanıtma ve Keşfetme","Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Uluslararası Düşünme"]},{"tip":"tablo","yon":"yatay","sutun":["Fark ettim ki","Neden böyle?","Açıklamalar","Neden böyle düşünüyorum?"],"adim":[["Fark ettim ki...","Bu nesnede ilginç bir şey fark et."],["Neden böyle?","Neden böyle olduğunu sor."],["Açıklamalar","Arkadaşların olası açıklamalar önerir."],["Gerekçe","Bunu düşünmene ne neden oldu?"]],"amac":"Bir şeyin neden öyle olduğunu anlamaya, neden-sonuç ve amaç açıklaması kurmaya yöneltir.","ne":"Masadaki bir nesne, şiir, olay. Cevabı kitaptan değil birlikte kurun; önce öğretmen soru sormayı örneklesin.","id":"aciklama-oyunu","ad":"Açıklama Oyunu","kat":["Fikirleri Tanıtma ve Keşfetme","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"gunluk","yon":"dikey","adim":[["Bu hafta fark ettiklerim","Okul dışında bu konuyla ilgili gördüğüm, duyduğum şeyleri her gün kaydediyorum."],["Bağlantı","Bu fikirler okulda öğrendiklerimle nasıl bağlantılı?"],["Hayatımda","Öğrendiklerimi hayatımın başka yerlerinde nasıl kullanabilirim?"]],"amac":"Okulda öğrenilenle okul dışı dünya arasındaki bağlantılara duyarlılığı artırır, içsel motivasyonu besler.","ne":"Bir hafta boyunca evde ve yolda tutulur. Hafta sonunda paylaşın; Eskiden düşünürdüm, şimdi düşünüyorum ile kapatın.","id":"hafta-boyunca-yuruyus","ad":"Hafta Boyunca Yürüyüş","kat":["Fikirleri Tanıtma ve Keşfetme"]},{"tip":"merkez","yon":"yatay","adim":[["Parçalar ve etkileşimler","Hangi parçalar birbirini etkiliyor?"],["Zaman içinde değişim","Zamanla nasıl değişti, nasıl değişebilir?"],["Bakış açıları","Kimler buna farklı bakar?"],["Gerçek ve kanıt","Neyin doğru olduğunu nasıl biliyoruz?"],["Gizemler","Hâlâ bilmediğimiz ne var?"]],"amac":"Bir konunun hangi yönlerden karmaşık olduğunu kavram haritasıyla düzenlemeye ve düşünme derinliğini görmeye yardım eder.","ne":"Konuyu ortaya yazın, öğrenciler her karmaşıklık türünü değerlendirir. Her tür her konuya uymaz, uymayanı atlayın. Kategoriler PDF'teki diyagramdan uyarlanmıştır, kontrol edin.","id":"karmasik-olabilecek-seyler","ad":"Karmaşık Olabilecek Şeyler","kat":["Fikirleri Tanıtma ve Keşfetme","Nesnelerin ve Sistemlerin Araştırılması","Perspektif Alma"]},{"tip":"izgara","yon":"yatay","adim":[["Güzellik","Bu resimde ya da hikâyede güzelliği bulabilir misin?"],["Gerçek","Bunda gerçeği bulabilir misin?"],["Güzellik gerçeği nasıl gösterir?","Güzellik gerçeği ortaya çıkarmaya nasıl yardım eder?"],["Güzellik gerçeği nasıl saklar?","Güzellik gerçeği nasıl gizleyebilir?"]],"amac":"Haber, resim ve hikâyelerin bir konuyu nasıl temsil ettiğini eleştirel olarak incelemeyi sağlar.","ne":"Fotoğraf, haber, resimli kitap. Fotoğrafların her zaman gerçeği gösterdiği yanılgısına dikkat edin; son iki soruda sözcükleri yer değiştirebilirsiniz.","id":"guzellik-ve-gercek","ad":"Güzellik ve Gerçek","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Uluslararası Düşünme"]},{"tip":"hedef","yon":"dikey","adim":[["Ana amaç","Bu şey ne için yapılmış?"],["Parçalar ve amaçları","Parçaları neler, her biri ne işe yarıyor? Çok akıllıca olanı yıldızla."],["Hedef kitle","Bu kimin için yapılmış?"]],"amac":"Sıradan şeylerin arkasındaki yaratıcı düşünceyi fark ettirir; amaç ve hedef kitle üzerinden anlamayı derinleştirir.","ne":"Kalem, kapı kolu, oyuncak ya da teneffüs gibi bir düzen. Hedef tahtasını çizin, öğrenciler yapışkan notla doldursun, yıldızlıları sonunda konuşun.","id":"yaratici-av","ad":"Yaratıcı Av","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Nesnelerin ve Sistemlerin Araştırılması","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"liste","yon":"dikey","adim":[["Soru listesi","Bu nesne ya da konu hakkında aklına gelen soruları yaz."],["Dönüştür","Bazı soruları hayal gücüne çevir: Eğer ... olsaydı nasıl olurdu? Ne değişirdi?"],["Hayal ederek keşfet","Bir soruyu seç. Hikâye yaz, resim çiz, canlandır ya da hayali röportaj yap."],["Düşün","Bu konuda hangi yeni fikirlerin oldu?"]],"amac":"İlginç sorular kurmayı ve onları hayal gücüyle keşfetmeyi sağlar.","ne":"Konu başında, ortasında ve sonunda. Önce 'iyi soru nedir' diye konuşun, ilk seferde tüm sınıfla yapın.","id":"yaratici-sorular","ad":"Yaratıcı Sorular","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Olasılıklar ve Benzetmeler Üretmek","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"izgara","yon":"yatay","adim":[["Mesaj","Burada sana ne anlatılmak isteniyor?"],["Kim, neden?","Bu mesajı kim vermeye karar verdi? Neden?"],["Başka yorum","Bu başka nasıl anlaşılabilir?"],["Bence doğru olan","Bunda neyin doğru olduğuna inanıyorum? Neden böyle düşünüyorum?"]],"amac":"Bilginin olduğu gibi kabul edilmemesi gerektiğini, kanıt aramayı ve farklı yorumları görmeyi öğretir.","ne":"Haber, reklam, tarihî olay ya da görsel. Görseli parça parça gösterip sonunda bütününü açmak etkilidir.","id":"gercekler-mi-kurgu-mu","ad":"Gerçekler mi Kurgu mu?","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"eksen","yon":"yatay","eksen":["Kesin yanlış","Belirsiz","Kesin doğru","Az önemli","Çok önemli"],"adim":[["Fikirleri yerleştir","Bu fikir doğru mu, yanlış mı, yoksa arada bir yerde mi? Çizgiye yerleştir."],["Neden belirsiz?","Bu fikri belirsiz ya da kesin yapan ne?"],["Ne kadar önemli?","Bunu önemli yapan ne? Yukarı ya da aşağı taşı."]],"amac":"Daha fazla düşünmeyi hak eden 'sıcak noktaları', yani belirsiz ve önemli fikirleri fark etmeyi öğretir.","ne":"Öğrencilerin biraz bildiği somut durumlarla (teneffüs kavgası, haberdeki olay). Yanlış bilgiyi hemen düzeltmeyin, kolaylaştırıcı kalın.","id":"sicak-noktalar","ad":"Sıcak Noktalar","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"izgara","yon":"yatay","adim":[["Hikâye","Anlatılan hikâye, gizli hikâye, mesaj ne?"],["Güzellik","Çekici, ustaca ya da alışılmadık olan ne?"],["Yapı","Hangi teknik, biçim ve yöntem kullanılmış?"],["Duygu ve hareket","Nerede sürpriz, gerilim, duygu var?"],["Bağlantılar","Başka eserlere, tarihe, bana ya da sanatçının hayatına bağlantısı ne?"]],"amac":"Yaratıcı bir esere farklı katmanlardan analitik bakmayı sağlar.","ne":"Önce esere yakından baktırın, sonra katman seçtirin. İlk seferde katmanları tek tek tüm sınıfla tanıtın; iki eseri karşılaştırmak için de kullanılabilir.","id":"katmanlar","ad":"Katmanlar","kat":["Fikirlerin Daha Derinlemesine İncelenmesi"]},{"tip":"elmas","yon":"dikey","adim":[["Sol: birinci kazanç","Bu tarafı seçersek ne kazanırız? Buraya o yönde seçenekler."],["Sağ: ikinci kazanç","Öbür tarafı seçersek ne kazanırız? Buraya o yönde seçenekler."],["Alt: orta yol","İkisinin arasında uzlaşan seçenekler"],["Üst: akıllı çözüm","İkisinin de iyisini alan yaratıcı çözüm var mı?"],["Ne öğrendik?","Bu seçenekleri bulmak durumu anlamamıza nasıl yardım etti?"]],"amac":"Karar vermeyi zorlaştıran gerilimleri görmeyi ve zıtlıkları birleştiren yaratıcı seçenekler aramayı sağlar.","ne":"Sınıf kararı, hikâyedeki bir ikilem. Sol ve sağ köşeler seçenek değil, zıt yöne çeken kazançlardır; son seçim zorunlu değil.","id":"secenekler-elmasi","ad":"Seçenekler Elması","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Olasılıklar ve Benzetmeler Üretmek"]},{"tip":"patlama","yon":"yatay","adim":[["Açık seçenekler","Hemen akla gelen seçenekler neler?"],["Gizli seçenekler","Başka hangi yollar olabilir? Fikirleri birleştir, başka birinin yerine geç, çılgın fikirler de olur."],["Ne öğrendik?","Seçenekleri bulmak durumu anlamamıza nasıl yardım etti?"]],"amac":"Karar durumlarında gözden kaçan gizli seçenekleri bulmayı ve yaratıcı düşünmeyi teşvik eder.","ne":"Sınıf ya da kişisel karar, hikâye, haber. Patlama diyagramında ışınlara yapışkan not eklenir; hızlı oylamayla bitirebilirsiniz.","id":"secenekler-patlamasi","ad":"Seçenekler Patlaması","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Olasılıklar ve Benzetmeler Üretmek"]},{"tip":"kolon","yon":"yatay","adim":[["Parçalar","Sistemin parçaları neler?"],["İnsanlar","Bu sisteme kimler bağlı?"],["Etkileşimler","İnsanlar birbirleriyle ve parçalarla nasıl etkileşiyor?"],["Değişirse","Bir parça değişirse kimler ve neler etkilenir?"]],"amac":"Bir sisteme yakından bakmayı, kimlerin katıldığını görmeyi ve değişikliklerin sonuçlarını düşünmeyi destekler.","ne":"Yemekhane sırası, servis, geri dönüşüm gibi çocuğun yaşadığı bir sistemle. Sistemin sınırını önceden belirleyin.","id":"parcalar-insanlar-etkilesimler","ad":"Parçalar, İnsanlar, Etkileşimler","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Nesnelerin ve Sistemlerin Araştırılması"]},{"tip":"halka","yon":"dikey","adim":[["Toplumumda","Bu konu bizim mahallemizde, şehrimizde nasıl yaşanıyor?"],["Ülkemde başka bir yerde","Ülkemizde başka bir şehir ya da kasabada nasıl?"],["Doğuda ya da batıda bir ülkede","İnsanların farklı düşünebileceği bir ülkede nasıl?"],["Kuzeyde ya da güneyde bir ülkede","Başka bir ülkede nasıl görülüyor?"],["Neden?","Benzerlikleri ve farklılıkları ne açıklayabilir?"]],"amac":"Bir konunun yakındaki ve uzaktaki toplulukları nasıl etkilediğini karşılaştırarak çok yönlü bakış kazandırır.","ne":"Beslenme, su, bayramlar gibi farklı yaşanan konularla. Genelleme ve klişelere hemen 'Bunu söylemene ne neden oldu?' ile yanıt verin.","id":"mesafeye-gore-yansitma","ad":"Mesafeye Göre Yansıtma","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma"]},{"tip":"zaman","yon":"yatay","adim":[["Şimdi ne biliyorum?","Bu konu hakkında ne düşünüyorum, ne biliyorum?"],["Geçmişe git","10 yıl, 100 yıl, 1000 yıl önce bu konu nasıldı?"],["Geleceğe git","10 yıl, 100 yıl, 1000 yıl sonra nasıl olacak? Neden böyle düşünüyorum?"],["Şimdi nasıl görüyorum?","Düşüncem nasıl değişti?"]],"amac":"Bir konuya kendi yaşam süresinden çok daha geniş bir zaman ölçeğinden bakmayı sağlar.","ne":"Okul, oyun, ulaşım, iletişim gibi konular. Küçüklerde 'dedemin çocukluğu, ben, torunum' gibi yakın dilimler seçin; her adımı ayrı renkle yazdırın.","id":"zaman-icinde-yansitma","ad":"Zaman İçinde Yansıtma","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma"]},{"tip":"isik","yon":"dikey","adim":[["Kırmızı ışık","Burada dur! Çok emin konuşuyor ama kanıt yok, abartıyor, kızgın, kendi çıkarını düşünüyor."],["Sarı ışık","Dikkat! Biraz şüpheli: herkes diyor ki, bence, belki."],["Neler öğrendik?","Bir şeyin doğru olmayabileceğini hangi işaretlerden anlarız?"]],"amac":"Doğruluğu şüpheli olabilecek anların işaretlerini fark etmeyi ve dikkat edilmesi gereken alanları görmeyi öğretir.","ne":"Reklam, söylenti, haber, bir hikâyedeki iddia. İşaret listesini birlikte büyütün; derin inceleme için başka bir rutine geçin.","id":"kirmizi-isik-sari-isik","ad":"Kırmızı Işık, Sarı Işık","kat":["Fikirlerin Daha Derinlemesine İncelenmesi"]},{"tip":"izgara","yon":"yatay","sutun":["Açık","Kontrol etmem gerekiyor"],"satirlar":["Gerçekler ve olaylar","Düşünceler ve duygular"],"adim":[["Gerçekler ve olaylar","Ne oldu? Kanıtı ne?"],["Düşünceler ve duygular","Kişiler ne düşünüyor, ne hissediyor? Kanıtı ne?"],["Benim yargım","Bunlara bakarak bu durum hakkında en iyi kararım ne?"]],"amac":"Gerçeği, düşünceyi ve yargıyı ayırt etmeyi; fikir ve duyguları düzenlemeyi sağlar.","ne":"Bir hikâye, haber ya da sınıfta yaşanan bir anlaşmazlık; konu araştırılırken ortada. Öğrenciler gazete muhabiri olduklarını hayal eder.","id":"muhabirin-not-defteri","ad":"Muhabirin Not Defteri","kat":["Fikirlerin Daha Derinlemesine İncelenmesi"]},{"tip":"kolon","yon":"yatay","adim":[["Ne algılayabilir?","Bu kişi ya da şey neyi görür, duyar, fark eder?"],["Ne bilir, neye inanır?","Bu kişi ya da şey neyi bilir ya da neye inanır?"],["Neyi önemser?","Bu kişi ya da şey için ne önemli?"]],"amac":"Bir karakterin ya da nesnenin yerine geçerek farklı bakış açılarını keşfetmeyi ve konuyu canlandırmayı sağlar.","ne":"Resim, hikâye, tarihî olay, hatta bir kesrin paydası. Öğrenciler o bakıştan konuşur ya da yazar; sınıf kim olduğunu tahmin edebilir.","id":"iceri-adim-at","ad":"İçeri Adım At","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"satir","yon":"dikey","adim":[["Tavır al","İkilemi oku. Senin görüşün ne? Nedenini not al."],["Dinle","Arkadaşlarının görüşlerini dinle, kendi görüşünü paylaş."],["Yeniden bak","Aklına gelmeyen ne duydun? Görüşün değişti mi, ne değişti?"],["Ötesine bak","Bu durum sana başka hangi durumları hatırlatıyor?"]],"amac":"Net doğru ya da yanlışın olmadığı ikilemlerde kendi görüşünü kurmayı, başkalarını dinlemeyi ve yeniden düşünmeyi destekler.","ne":"Dijital yaşam, sınıf kuralı, paylaşma ikilemleri. Önce sınıf kurallarını hatırlatın: anlamak için dinle, 'ben' diye konuş.","id":"bir-tavir-al","ad":"Bir Tavır Al","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"kolon","yon":"yatay","adim":[["Düşün","Bu kişi bu sistemde ne yapıyor? Bunu nereden biliyorum?"],["Hisset","Bu kişi ben olsaydım nasıl hissederdim? Neden?"],["Önemse","Bu kişi ben olsaydım neyi önemserdim?"]],"amac":"Bir sistemdeki farklı kişilerin konumlarına göre farklı düşündüğünü, hissettiğini ve önemsediğini anlamayı sağlar.","ne":"Okul servisi, kantin, kütüphane gibi çocuğun yaşadığı bir sistem ya da bir hikâye. Canlandırma ile yapın, aynı kişiyi iki farklı biçimde oynatın.","id":"dusun-hisset-onemse","ad":"Düşün, Hisset, Önemse","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Nesnelerin ve Sistemlerin Araştırılması"]},{"tip":"halat","yon":"yatay","uclar":["Doğru","Yanlış"],"adim":[["Soru","Tartıştığımız iddia: Bu doğru mu?"],["Doğru tarafına çekenler","Doğru olduğunu gösteren kanıtlar"],["Yanlış tarafına çekenler","Yanlış olduğunu gösteren kanıtlar"],["Ya ... olsaydı?","Daha fazla bilgi isteyen sorular halatın üstüne"],["Şimdi ne düşünüyoruz?","Karar verebilir miyiz? Cevap gri bir alanda mı?"]],"amac":"Bir doğruluk sorusunda farklı kanıtların çekişini tartarak dikkatli akıl yürütmeyi ve siyah-beyaz görünen konuların karmaşıklığını görmeyi sağlar.","ne":"Her iki tarafta kanıt olan bir iddia ile. Tahtaya ip çizin ya da duvara ip bantlayın, kanıtları yapışkan notla ekleyin.","id":"gercek-icin-halat-cekme","ad":"Gerçek İçin Halat Çekme","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"halat","yon":"yatay","uclar":["Bir taraf","Öbür taraf"],"adim":[["İkilem","Hangi zor durumu konuşuyoruz? İki ucu yazalım."],["Bu tarafa çekenler","Bu tarafı desteklemek için nedenler"],["Öbür tarafa çekenler","Öbür tarafı desteklemek için nedenler"],["Ya ... olsaydı?","Kararı değiştirebilecek sorular"],["Şimdi ne düşünüyorum?","Fikrim değişti mi?"]],"amac":"Bir adalet ikileminin iki tarafını çeken güçleri anlamayı ve dikkatli akıl yürütmeyi sağlar.","ne":"Oyun başladıktan sonra oyuna arkadaş almak gibi sınıftan ikilemler. Önce herkes tarafını seçer, sonra iki taraf için de neden üretir.","id":"halat-cekme","ad":"Halat Çekme","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"izgara","yon":"yatay","adim":[["Hikâye","Burada anlatılan hikâye ne?"],["İnsan hikâyesi","Bu işin içindeki insanların hikâyesi ne?"],["Dünya hikâyesi","Bu, dünyadaki hangi büyük hikâyenin parçası?"],["Yeni hikâye","Burada yeni olan ne?"],["Anlatılmayan hikâye","Burada ne anlatılmamış, kim görünmüyor?"]],"amac":"Görsel ve metinlerdeki anlam katmanlarını, insan hikâyesini ve anlatılmayanı keşfetmeyi sağlar.","ne":"Haber fotoğrafı, belgesel kesiti, tarihî görsel. Hedefinize göre soruların bir kısmını seçebilir, sırasını değiştirebilirsiniz.","id":"hikayeleri-aciga-cikarma","ad":"Hikayeleri Açığa Çıkarma","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Uluslararası Düşünme"]},{"tip":"satir","yon":"dikey","adim":[["Fark et","Esere yakından bak. Neler fark ediyorsun?"],["Değerler","Bu eser bizi hangi değerler üzerine düşündürüyor (adalet, saygı, gelenek, güvenlik)?"],["Kimlikler","Bu eser kimden bahsediyor, kime sesleniyor? Dışarıda kalan biri var mı?"],["Eylemler","Bu eser bizi ne yapmaya çağırıyor?"],["Yeniden bak","Esere tekrar bak. Ekleyecek yeni fikrin var mı?"]],"amac":"Sanat eserlerinin toplumsal yönlerini değer, kimlik ve eylem üzerinden keşfetmeyi sağlar.","ne":"Kolayca fark edilen bir yurttaşlık teması taşıyan eserle. Her başlığın anahtar sorusu önemli, derinleştirme sorularından birkaçını seçin.","id":"degerler-kimlikler-eylemler","ad":"Değerler, Kimlikler, Eylemler","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Sanat, Resim ve Nesneleri Keşfetmek","Uluslararası Düşünme"]},{"tip":"zaman","yon":"yatay","adim":[["İncele","Bu şey bugünkü hâline nasıl geldi? Değişmesine kim ya da ne neden oldu?"],["Tahmin et","Gelecekte nasıl değişebilir?"],["Hayal et ve yarat","Bu değişimin zorluğunu fırsata çevirseydik ne yaratabilirdik?"]],"amac":"Değişimin nasıl olduğunu inceleyip geleceği tahmin etmeyi ve olasılıkları hayal edip yaratma cesaretini besler.","ne":"Okul, oyuncak, ulaşım gibi değişen şeylerle. 'Tahmin' sözcüğü güvenli risk almayı kolaylaştırır; atık malzemeyle tasarım yaptırabilirsiniz.","id":"ne-olabilir","ad":"Ne Olabilir","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Perspektif Alma"]},{"tip":"izgara","yon":"yatay","adim":[["Keşfet","Ben kimim? Bugünkü ben nasıl oluştu?"],["Bağlan","Kimlerle ve nelerle bağlıyım? (aile, arkadaşlar, takım)"],["Tanımla","Biri beni tanımak isteseydi beni ne anlatırdı?"],["Ait ol","Nereye ait hissediyorum? Birden çok yere ait olabilir miyim?"]],"amac":"Kimliğin çok yönlülüğünü keşfetmeyi, yargıyı ertelemeyi ve insanlar arasındaki benzerlikleri görmeyi teşvik eder.","ne":"Kimlik hassas olabilir; sınıfınıza uymayan adımı çıkarın. Farklılıklar kadar beklenmedik benzerlikleri de aratın.","id":"ben-kimim","ad":"Ben Kimim?","kat":["Fikirlerin Daha Derinlemesine İncelenmesi","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"satir","yon":"dikey","adim":[["Bul","Gözünü yakalayan bir nesne ya da sahne bul. Ne olduğunu bir cümleyle söyle."],["Yakala","En az 5-10 dakika yavaşça çiz ya da farklı açılardan fotoğrafla. Güzel olması gerekmez."],["Açıkla","Ne kadar karmaşık olduğunu yaz ya da arkadaşına anlat."],["Merak et","Bu nesne hakkında hangi yeni sorularım var?"]],"amac":"Çizim ya da fotoğrafla yavaşlayıp yakından bakarak gündelik şeylerdeki karmaşıklığı görmeyi sağlar.","ne":"Bahçede bir yaprak, sınıfta bir makas. Çizimin tekniğini değil gözlemi övün; 4-6 karelik hızlı taslak ızgarası işe yarar.","id":"yavas-karmasiklik-yakalama","ad":"Yavaş Karmaşıklık Yakalama","kat":["Nesnelerin ve Sistemlerin Araştırılması","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"daire","yon":"dikey","adim":[["Nefes al","Rahat otur. Üç kez derin nefes al."],["Fark et","Şu an aklında ve kalbinde ne var? Dairenin içine yaz ya da çiz."],["Kenara koy","Öğrenmek için şimdilik neyi kenara koyabilirsin? Onları sayfanın kenarına taşı."],["Merkezde tut","Öğrenirken neyi yanında tutmak istersin? Onları ortaya getir."]],"amac":"Kendini anlamayı, kendini yönlendirmeyi ve sakin, şefkatli bir dikkatle öğrenmeye geçmeyi destekler.","ne":"Güne başlarken ya da teneffüs dönüşü. Önce birlikte esneyin, sakin ve acelesiz bir sesle yönetin; isteyen paylaşsın.","id":"ogrenme-icin-alan-yaratma","ad":"Öğrenme İçin Alan Yaratma","kat":["Perspektif Alma","Fikirleri Sentezleme ve Düzenleme"]},{"tip":"izgara","yon":"yatay","adim":[["Belirle","Bu durumda kimler var? Hangi zorlukla karşılaşıyorlar?"],["Hisset","Her biri ne hissediyor olabilir? Neden zor?"],["Hayal et","Ne yapılabilir? Çok fikir üret, herkesi en iyi hissettireni daire içine al."],["Söyle","Seçtiğin fikirde kişiler ne söyleyebilir? Gerçekten böyle söyler miydin?"]],"amac":"Bakış açısı almayı, empatiyle sorun çözmeyi ve nazik iletişim dilini destekler.","ne":"Arkadaşlık, paylaşma, dijital mesajlaşma ikilemleriyle; 15 dakikada yapılabilir, sık tekrarlayın.","id":"duygular-ve-secenekler","ad":"Duygular ve Seçenekler","kat":["Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Olasılıklar ve Benzetmeler Üretmek"]},{"tip":"paket","yon":"dikey","adim":[["Hedefim (hazine)","Ulaşmak istediğim hedef ne? Paketin içindeki hazine o."],["Düşün","Öğrendiğim bu konunun hedefimle bağlantısı ne? İlk katmanı aç."],["Tanımla","Hangi bağlantı benim için önemli, neden? Bir katman daha."],["Keşfet","Bu bağlantıları anlamak için neler yapabilirim? Bir katman daha."],["Harekete geç","Hazineme ulaşmak için ne yapacağım?"]],"amac":"Okulda ve dışında öğrenilenlerin hedeflere nasıl bağlandığını görerek içsel motivasyonu besler.","ne":"Kısa vadeli, spor ya da sosyal hedeflerle. Paket açma oyununu bilmeyenlere kısaca anlatın.","id":"paketi-uzat","ad":"Paketi Uzat","kat":["Perspektif Alma"]},{"tip":"satir","yon":"dikey","adim":[["İlk izlenim","İlk bakışta ne düşündün?"],["Bakış açıları","Başka kimler bunu nasıl görür? Ne söylerlerdi?"],["Aynı ve farklı","Benzerlikler neler, farklılıklar neler? Hem aynı hem farklı nasıl olabilir?"]],"amac":"Benzerlik ve farklılıkların yüzeyinin ötesine geçmeyi, ikili karşıtlıkları sorgulamayı sağlar.","ne":"Farklı ülkelerin okulları, aynı okunan farklı yazılan sözcükler gibi. Fikrini değiştirmenin değerli olduğunu siz örnekleyin.","id":"ayni-ve-farkli","ad":"Aynı ve Farklı","kat":["Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"izgara","yon":"yatay","adim":[["Aynı","Bu kişiyle hangi açılardan benzer olabiliriz?"],["Farklı","Hangi açılardan farklı olabiliriz?"],["Bağlan","İnsan olarak hangi açılardan bağlıyız?"],["Etkileşim","Şansım olsaydı ona ne sormak, söylemek ya da yapmak isterdim?"]],"amac":"Empatiyle bakış açısı almayı ve farklılıklar arasında köprü kurmayı besler.","ne":"Bir hikâye karakteri, mektup arkadaşı, başka bir ülkeden bir çocuğun fotoğrafı ile.","id":"ayni-farkli-baglan-etkilesim","ad":"Aynı Farklı Bağlan Etkileşim","kat":["Perspektif Alma","Uluslararası Düşünme"]},{"tip":"izgara","yon":"yatay","adim":[["Duygular","Bu kişi bu durumda neler hissediyor olabilir? Birden çok duygu düşün."],["Güç","Bu kişinin güçlü yanları, zenginlikleri neler?"],["Bağlantılar","İnsan olarak hangi yollarla bağlantı kurabiliriz?"],["İnsan onuru","Onu onurlandıran hangi sözcükleri seçerdim?"],["Düşün","Bu deneyimde düşüncemde, duygumda ne değişti? Hangi sorularım var?"]],"amac":"Başka bir insanı bütünüyle, gücü ve onuruyla görmeyi, damgalamanın karşısında durmayı besler.","ne":"Genellikle görünmez kalan biriyle ilgili hikâye, görsel ya da video. Zor bir konuysa umut ve eylem olanaklarını da konuşun.","id":"gormeye-calis","ad":"Görmeye Çalış","kat":["Perspektif Alma","Uluslararası Düşünme"]},{"tip":"satir","yon":"dikey","adim":[["Dur","İddia ne? Bildiğim ve emin olmadığım şeyler neler?"],["Bak","Nereye bakabilirim? Hangi kaynaklar bana bilgi verir?"],["Dinle","Kaynaklar ne diyor? Kaynak taraflı olabilir mi?"]],"amac":"Bir iddiayı netleştirip kaynakları açık fikirle ve eleştirel biçimde araştırmayı öğretir.","ne":"Bir söylenti, reklam ya da 'duydum ki' cümlesiyle. Kaynakları ve olası taraflarını duvarda bir çizelgede biriktirin.","id":"dur-bak-dinle","ad":"Dur, Bak, Dinle","kat":["Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"izgara","yon":"yatay","adim":[["Anlatılan hikâye","Burada bize hangi hikâye anlatılıyor?"],["Anlatılmayan hikâye","Ne dışarıda bırakılmış? Hangi açı eksik?"],["Benim hikâyem","Bence anlatılması gereken hikâye ne?"]],"amac":"Olay ve insanların nasıl anlatıldığını, neyin dışarıda kaldığını görmeyi ve kendi duruşunu kurmayı sağlar.","ne":"Haber, tarih metni, okuma kitabı. Soruları bu sırayla sorun; 'onun hikâyesi, bizim hikâyemiz' ile çoğaltabilirsiniz.","id":"hikayeler","ad":"Hikayeler","kat":["Perspektif Alma"]},{"tip":"halka","yon":"dikey","adim":[["Benim için","Bu konu benim için neden önemli olabilir?"],["Çevrem için","Ailem, arkadaşlarım, şehrim için neden önemli olabilir?"],["Dünya için","Dünya için neden önemli olabilir?"]],"amac":"Bir konunun kişisel, yerel ve küresel önemini fark etme eğilimini besler.","ne":"Ünite başında konu tanıtıldıktan sonra. Odak sorusunu net kurun; her adımı ayrı yapın, uzak bir konuda dünyadan başlayıp içe gelin.","id":"3-neden","ad":"3 Neden","kat":["Perspektif Alma","Uluslararası Düşünme"]},{"tip":"cember","yon":"yatay","adim":[["İddia","Bu iddiayı kim, hangi durumda söyledi? Ne önemliydi?"],["Bakış açıları","Bu iddiaya kimler farklı açıdan bakar? Listele."],["Canlandır","Bir bakış açısı seç: Benim bakış açım... Bence bu doğru/yanlış/belirsiz çünkü... Fikrimi değiştirecek şey..."],["Geri çekil","Çemberin dışına çık. Şimdi ne düşünüyorum, hangi sorularım var?"]],"amac":"Bir iddianın farklı bakış açılarından nasıl göründüğünü hayal ederek bağlamın inanılanı nasıl etkilediğini görmeyi sağlar.","ne":"İddia netleştikten sonra. Öğrenciler çember olur, sırayla canlandırır; bakışları tahtadaki çembere yazın.","id":"kim-icin-dogru","ad":"Kim İçin Doğru?","kat":["Perspektif Alma","Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Olasılıklar ve Benzetmeler Üretmek","Uluslararası Düşünme"]},{"tip":"tablo","yon":"yatay","sutun":["İdeale uyuyor mu?","Ölçütlere uyuyor mu?","Duruma uyuyor mu?","Bana uyuyor mu?"],"satir_adi":"Seçenek","adim":[["İdeale uydur","En güzel durum nasıl olurdu? Her seçenek buna ne kadar uyuyor?"],["Ölçütlere uydur","Bizim için önemli olanlar neler? Her seçenek bunlara ne kadar uyuyor?"],["Duruma uydur","Zamanımız, malzememiz ne kadar? Her seçenek buna uyuyor mu?"],["Kendine uydur","Kendini bu seçeneği yaparken hayal et. Hangisi sana uygun geliyor?"]],"amac":"Seçenekleri farklı ölçülere göre yaratıcı ve dikkatli biçimde değerlendirmeyi sağlar.","ne":"Sınıf gezisi yeri, proje konusu, oyun seçimi gibi kararlar. Seçenekleri satırlara yazın, her sütuna yıldız ya da gülen yüz koydurun.","id":"uygun-mu","ad":"Uygun mu?","kat":["Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"oncesonra","yon":"yatay","bas":["Burada, şimdi","Orada, o zaman"],"adim":[["Burada, şimdi","Bugün insanlar bu konuda ne düşünüyor, neye değer veriyor?"],["Orada, o zaman","Eskiden insanlar bu konuda ne düşünüyordu?"],["Karşılaştır","Neden değişti? Eskiden insanlar neden böyle düşünmüyordu?"],["Daha fazlası","O zamanki insanların düşüncesini nasıl daha iyi öğrenebiliriz?"]],"amac":"Geçmişteki bakış açılarını düşünmeyi ve düşüncenin zamanla nasıl değiştiğini, bugünkü yargılarımızın bağlamdan etkilendiğini görmeyi sağlar.","ne":"Çocuk hakları, kadınların okuması, çocuk işçiliği gibi zamanla değişen konular. Zaman yolcusu canlandırmasıyla tüm sınıfla yapın.","id":"burada-simdi-orada-o-zaman","ad":"Burada Şimdi / Orada O Zaman","kat":["Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma"]},{"tip":"izgara","yon":"yatay","adim":[["Gör","Ne görüyorsun?"],["Hisset","Buna bakarken içinde hangi duygular uyanıyor?"],["Düşün","Bu sana ne düşündürüyor?"],["Merak et","Bunun hakkında neyi merak ediyorsun?"]],"amac":"Dikkatli gözleme duyguyu da ekler; düşünceli yorumu, merakı ve sorgulamayı başlatır.","ne":"Sanat eseri, fotoğraf, müzik. Önce bireysel düşünme zamanı verin; yorumları 'neden' ile destekletin.","id":"gor-hisset-dusun-merak-et","ad":"Gör Hisset Düşün Merak Et","kat":["Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Uluslararası Düşünme"]},{"tip":"tablo","yon":"yatay","sutun":["Farklı düşünüyoruz","Aynı düşünüyoruz"],"satir_adi":"","satirlar":["Gerçekler","Değerler","Çıkarlar","Ne yapalım?"],"adim":[["Gerçekler","Hangi gerçeklerde ayrılıyoruz, hangilerinde birleşiyoruz?"],["Değerler","Hangi değerlerde ayrılıyoruz, birleşiyoruz?"],["Çıkarlar","Kimin neyi kazanıp kaybettiği konusunda neler farklı, neler ortak?"],["Ne yapalım?","Ne yapılması gerektiği konusunda nerede ayrılıyor, nerede birleşiyoruz?"]],"amac":"Büyük tartışmaların kaynaklarını görmeyi ve uzlaşılan noktaları fark etmeyi sağlar.","ne":"Sınıf ya da okul tartışması, teneffüs kuralı. Uzlaşı şart değil; ortak noktalar ilerlemenin başlangıcıdır.","id":"cikmaz-noktalar","ad":"Çıkmaz Noktalar","kat":["Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Uluslararası Düşünme"]},{"tip":"izgara","yon":"yatay","adim":[["Bağlantılar","Metin ile hayatım ya da öğrendiklerim arasında hangi bağlantıları kuruyorum?"],["Meydan okuma","Metindeki hangi fikre itiraz etmek istiyorum?"],["Kavramlar","Metindeki hangi önemli fikirleri aklımda tutmalıyım?"],["Değişiklikler","Metin bizde hangi değişiklikleri öneriyor?"]],"amac":"Metin temelli bir tartışmayı bağlantı, soru, ana fikir ve uygulama üzerinden yapılandırır.","ne":"Okuma metninden sonra küçük gruplarda. Herkes önce her C için metinden bir yeri işaretler, sonra sırayla okuyup açıklar. 2-3 C de yeter.","id":"4-c","ad":"4 C","kat":["Tartışmaları, İkilemleri ve Perspektifleri Göz Önünde Bulundurma","Fikirleri Sentezleme ve Düzenleme"]},{"tip":"satir","yon":"dikey","adim":[["Ne biliyorum?","Bu eserde ne görüyorum ya da bu konu hakkında ne biliyorum?"],["Bir kategori seç","Çalgılar, bitkiler, oyuncaklar, şehirler, vücudun parçaları ya da kendi kategorin"],["Benzet","Bu konu bir tür ____ olsaydı ne olurdu?"],["Üç benzerlik","Hangi üç yönden birbirlerine benziyorlar?"]],"amac":"Benzetme ve metafor yoluyla yeni bir konuyu bilinen şeylere bağlamayı, yaratıcı düşünmeyi teşvik eder.","ne":"Öğretmen önceden çok çeşitli kategori listesi hazırlar. 'Kalp bir pompa gibidir çünkü...' gibi bir örnekle başlayın.","id":"yaratici-karsilastirmalar","ad":"Yaratıcı Karşılaştırmalar","kat":["Olasılıklar ve Benzetmeler Üretmek","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"satir","yon":"dikey","adim":[["Kontrol et","Teknoloji alışkanlıklarımı listele. Her birinin yanına bana nasıl hissettirdiğini gösteren bir yüz çiz."],["Seç","Değiştirmek istediğim bir alışkanlığı seç. Neden önemli?"],["Meydan oku","Bir hafta boyunca ne zaman, neyi farklı yapacağım? Onun yerine ne yapacağım?"],["Destekle","Yeni alışkanlığımı kolaylaştırmak için neler yapabilirim?"],["Takip et","Her gün: Bugün nasıl gitti? Ne zorlaştırdı, ne kolaylaştırdı?"]],"amac":"Dijital alışkanlıkları fark edip değerlendirmeyi ve iyi oluşu destekleyen küçük değişiklikler yapmayı sağlar.","ne":"Ekran süresi, tablet, oyun konuşulurken. Çok küçük bir hedefle başlamak başarıyı getirir; 'yapmayacağım' yerine 'onun yerine yapacağım' dedirtin.","id":"dijital-aliskanliklar-kontrolu","ad":"Dijital Alışkanlıklar Kontrolü","kat":["Olasılıklar ve Benzetmeler Üretmek"]},{"tip":"satir","yon":"dikey","adim":[["Hatırla","Bakmadan, öğrendiğin önemli fikirleri 2-3 dakikada listele."],["+1 ekle","Kâğıdını sağdakine ver. Önündeki listeye bir şey ekle: bir ayrıntı, eksik bir fikir ya da bir bağlantı. İki kez tekrarla."],["Gözden geçir","Kâğıdın sana dönünce eklenenleri oku, beğendiğin fikirleri ekle."]],"amac":"Önemli fikirleri belirlemeyi ve hemen hatırlamayla akılda tutmayı, grubun gücüyle notları zenginleştirmeyi sağlar.","ne":"Okuma, video ya da ders sonunda 10-15 dakika. Ders sırasında not almak yerine dinlemelerini isteyin.","id":"arti-1-rutin","ad":"Artı 1 Rutin","kat":["Fikirleri Sentezleme ve Düzenleme"]},{"tip":"halka","yon":"dikey","adim":[["Yakın çevremde","Arkadaşlarım, ailem, tanıdığım insanlar için ne yapabilirim?"],["Toplumumda","Okulumda, mahallemde ne yapabilirim?"],["Dünyada","Yakın çevremin ötesinde ne yapabilirim?"]],"amac":"Kişisel, yerel ve küresel alanlarda harekete geçme isteğini ve gücünü geliştirir; büyük sorunlar karşısında çaresizliği azaltır.","ne":"Atık, su, arkadaşlık gibi önemsenen bir konu konuşulduktan sonra. İç içe üç daire çizin; sonunda uygulanabilir bir eylem seçin.","id":"eylem-cemberleri","ad":"Eylem Çemberleri","kat":["Fikirleri Sentezleme ve Düzenleme","Uluslararası Düşünme"]},{"tip":"kolon","yon":"yatay","adim":[["Renk","Önemli bir fikri en iyi hangi renk anlatır? Neden?"],["Sembol","Başka bir fikri en iyi hangi basit sembol anlatır?"],["Görsel","Başka bir fikri en iyi hangi resim anlatır? Çiz."]],"amac":"Okunan, izlenen ya da dinlenen bir şeyin özünü sözcük kullanmadan renk, sembol ve görselle yakalamayı sağlar.","ne":"Okuma ya da izleme sonrasında. Önce önemli fikirleri tahtaya yazın, her biri için birlikte örnek verin; paylaşırken 'neden' sorun.","id":"renk-sembol-gorsel","ad":"Renk, Sembol, Görsel","kat":["Fikirleri Sentezleme ve Düzenleme"]},{"tip":"merkez","yon":"yatay","adim":[["Oluştur","Konu deyince aklına gelen fikirleri yaz."],["Sırala","En önemli fikirleri ortaya, daha uzak olanları kenara yerleştir."],["Bağla","Ortak yanı olan fikirleri çizgiyle birleştir, çizginin üstüne bağlantıyı yaz."],["Ayrıntılandır","Fikirlerden birini yeni fikirlerle büyüt."]],"amac":"Ön bilgiyi harekete geçirip fikirleri kavram haritasında düzenlemeyi ve bağlantı kurmayı sağlar.","ne":"Ünite öncesi ön değerlendirme ya da ünite içinde ara değerlendirme. Her eklemede farklı renk kalem kullanılırsa gelişim görünür.","id":"olustur-sirala-bagla-ayrintililastir","ad":"Oluştur-Sırala-Bağla-Ayrıntılılaştır","kat":["Fikirleri Sentezleme ve Düzenleme"]},{"tip":"gazete","yon":"dikey","adim":[["Manşet","Bu konunun en önemli yanını anlatan bir gazete başlığı yaz."],["Dünkü başlığım","Dün yazsaydım başlığım ne olurdu? Ne değişti?"]],"amac":"Bir konunun özünü ya da ana fikrini kısa ve çarpıcı biçimde yakalamayı sağlar.","ne":"Ders ya da tartışma sonunda. En iyi başlık yarışması değildir; arkadaşlarla paylaşıp farklı bakışları duymak için. Başlıkları saklayıp sonra karşılaştırın.","id":"basliklar","ad":"Başlıklar","kat":["Fikirleri Sentezleme ve Düzenleme","Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"satir","yon":"dikey","adim":[["Söylemek istediğim","Söylemek istediğim şu: ..."],["Başka nasıl söylerim? Neden?","Bunu başka nasıl söyleyebilirim? Kime, nerede söylüyorum? Neden böyle?"],["Bir kez daha","Bunu bir kez daha başka biçimde söyle. Ses tonum, yüz ifadem ne olur?"]],"amac":"Amaç, dinleyici ve duruma göre iletişim seçimleri yapmayı, farklı insanlarla iletişim kurmayı geliştirir.","ne":"Bir mesaj, afiş, sunum ya da arkadaşa söylenecek zor bir söz. 'Neden' yanıtlarını eşle paylaşmak şart.","id":"baska-nasil-ve-neden","ad":"Başka Nasıl ve Neden","kat":["Fikirleri Sentezleme ve Düzenleme","Uluslararası Düşünme"]},{"tip":"kolon","yon":"yatay","adim":[["Şaşırtan örüntü","Bu konuda sık görülen hangi örüntüler var? Seni en çok şaşırtanı seç."],["Başka nerede?","Aynı örüntü çok farklı hangi durumlarda da görülür?"],["Karşılaştır","İkisi nasıl benzer, nasıl farklı? Hangisi en önemli?"]],"amac":"Bir konudan şaşırtıcı örüntüler çıkarıp çok farklı durumlarda aramayı, taşınabilir bilgi kurmayı sağlar.","ne":"Besin zinciri, iyi karakter-kötü karakter, buluşlar gibi. Zorlanırlarsa 'seni ne şaşırttı?' diye sorun; zayıf benzetmeler de öğreticidir.","id":"tasinabilir-surpriz","ad":"Taşınabilir Sürpriz","kat":["Fikirleri Sentezleme ve Düzenleme"]},{"tip":"izgara","yon":"yatay","secmeli":true,"adim":[["En önemli nokta","Bugün öğrendiğin en önemli şey ne?"],["Zor gelen","Anlamakta zorlandığın, kafanı karıştıran ne?"],["Tartışmak istediğim soru","En çok hangi soruyu konuşmak istersin?"],["İlginç bulduğum","İlginç bulduğun bir şey ne?"]],"amac":"Bir öğrenme bölümünün özünü yakalamayı ve ortaya çıkan soruları görmeyi sağlar; çıkış bileti olarak öğretmene geri bildirim verir.","ne":"Ders, video ya da okuma sonunda. Çocuk dört kutudan yalnızca birini seçer; 3-5 dakika. Kartları toplayıp ertesi derse onlarla başlayın.","id":"not-al","ad":"Not Al","kat":["Fikirleri Sentezleme ve Düzenleme"]},{"tip":"kolon","yon":"yatay","adim":[["Sözcük","Dikkatini çeken ya da seni etkileyen sözcük"],["İfade","Seni etkileyen ya da düşündüren söz öbeği"],["Cümle","Metnin özünü yakaladığını düşündüğün cümle"],["Grupça konuşun","Hangi temalar çıkıyor? Ne tahmin edebiliriz? Metnin hangi yanı seçilmedi?"]],"amac":"Metnin özünü yakalamaya ve seçimlerin nedenlerini konuşarak anlam kurmaya yapı sağlar.","ne":"Okuma metninden sonra 4-6 kişilik gruplarda. Sırayla önce sözcükler, sonra ifadeler, sonra cümleler paylaşılır; neden seçildiği açıklanır.","id":"kelime-ifade-cumle","ad":"Kelime-İfade-Cümle","kat":["Fikirleri Sentezleme ve Düzenleme"]},{"tip":"hikaye","yon":"yatay","secmeli":true,"adim":[["Başlangıçsa","Bu resim bir hikâyenin başıysa sonra ne olur?"],["Ortasıysa","Bu resim hikâyenin ortasıysa önce ne oldu? Birazdan ne olacak?"],["Sonuysa","Bu resim hikâyenin sonuysa hikâye neydi?"]],"amac":"Hikâye anlatmanın gücüyle gözlemi, hayal gücünü ve bağlantı, örüntü ve anlam aramayı destekler.","ne":"Tablo, fotoğraf, resimli kitap sayfası. Yazma etkinliğinden önce çok iyi çalışır; önce Bakmak: On Kere İki ile sözcük biriktirin.","id":"baslangic-orta-son","ad":"Başlangıç, Orta, Son","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"kolon","yon":"yatay","adim":[["Renkler","Hangi renkleri görüyorsun?"],["Şekiller","Hangi şekilleri görüyorsun?"],["Çizgiler","Hangi çizgileri görüyorsun?"]],"amac":"Bir eserin ya da nesnenin biçimlerine dikkat çekerek ayrıntılı gözlemi destekler, betimleyici dil kazandırır.","ne":"Sanat eseri, yaprak, bina fotoğrafı. Yazmadan önce iyi bir ısınmadır; listeleri sonra yeniden açıp ilk seferde görülmeyenleri ekletin.","id":"renkler-sekiller-cizgiler","ad":"Renkler, Şekiller, Çizgiler","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"zincir","yon":"yatay","adim":[["1. kişi","Resmin bir bölümünü seç ve gördüğünü anlat."],["2. kişi","Aynı bölüme bir ayrıntı daha ekle."],["3. kişi","Daha da fazla ayrıntı ekle."],["4. kişi","Bir ayrıntı daha. Sonra yeni bir bölüm seçin."],["Şimdi yorum","Sadece gördüklerimizi söyledik. Şimdi ne düşünüyoruz?"]],"amac":"Ayrıntılara dikkatle bakmayı, zengin betimleme yapmayı ve gözlemle yorumu ayırmayı öğretir.","ne":"Resim, heykel, mikroskop görüntüsü, bitki. Elle ya da kâğıttan bir vizör yaptırıp küçük bölümlere odaklatın. Yorum en sona kalır.","id":"ayrintilandirma-oyunu","ad":"Ayrıntılandırma Oyunu","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"onx2","yon":"dikey","duyu":"dinle","adim":[["Dinle","Müziği sessizce dinle. Kulakların gezinsin."],["10 sözcük","Duyduğun her şey hakkında 10 sözcük ya da ifade yaz."],["Yeniden dinle","Bir kez daha dinle ve 10 sözcük daha ekle."]],"amac":"Yavaşlayıp müziği dikkatle dinlemeyi ve ilk izlenimin ötesine geçmeyi sağlar.","ne":"Kısa bir müzik parçasıyla. On fazla gelirse 3-5 ile başlayın; isteyen gözlerini kapatsın, ikinci dinlemede çizebilir.","id":"dinleme-on-kere-iki","ad":"Dinleme: On Kere İki","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"onx2","yon":"dikey","duyu":"bak","adim":[["Bak","Resme en az 30 saniye sessizce bak, gözlerin gezinsin."],["10 sözcük","Resmin herhangi bir yanı hakkında 10 sözcük ya da ifade yaz."],["Yeniden bak","Bir kez daha bak ve 10 sözcük daha ekle."]],"amac":"Yavaşlayıp ilk izlenimin ve göze batanın ötesinde dikkatli, ayrıntılı gözlem yapmayı sağlar.","ne":"Resim, fotoğraf, nesne. Yazma öncesi betimleyici sözcük biriktirir. On fazlaysa 3-5 ile başlayın; ikinci bakışta renk, şekil, çizgi aratın.","id":"bakmak-on-kere-iki","ad":"Bakmak - On Kere İki","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"izgara","yon":"yatay","adim":[["Gör","Esere dikkatle bak. Neler fark ediyorsun?"],["Düşün","Bu eser birlikte yaşamakla ilgili hangi fikir ve sorulara bağlanıyor?"],["Yap","Bir fikri seç ve bir şey yaparak ya da çizerek keşfet. 5 dakika, 1-3 malzeme."],["Tartış","Yaptığını ve keşfettiğin fikri anlat."]],"amac":"Üreterek düşünmeyi, sözcüklerle anlatması zor fikirleri yaparak keşfetmeyi sağlar.","ne":"Toplumsal bir yorum davet eden eserle. Atık malzeme, ip, folyo yeter; ürün değil süreç önemli, paylaşmak zorunlu değil.","id":"gor-dusun-yap-tartis","ad":"Gör Düşün Yap Tartış","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"izgara","yon":"yatay","adim":[["Gör","Dikkatle bak. Neleri fark ediyorsun?"],["Merak et","Aklına hangi sorular takılıyor?"],["Okula bağla","Bu, okulda öğrendiğin hangi derslerle bağlantılı olabilir?"],["Kendime bağla","Bu, kendi ilgi alanlarım ya da hobilerimle nasıl bağlantılı?"]],"amac":"Yakından bakmanın anlayışı genişlettiğini ve bilinçli aranırsa her yerde bağlantı bulunabileceğini fark ettirir.","ne":"Konu başında bir cetvel, harita, yaprak ya da kitap kapağıyla. Bir dakika sessizce baktırın, 'Başka ne görüyorsun?' diye sorun.","id":"gor-merak-et-baglan-x2","ad":"Gör, Merak Et, Bağlan x2","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"eksen","yon":"yatay","eksen":["Basit","","Karmaşık"],"adim":[["Bildiklerim","Bu konu hakkında bildiğin gözlem, bilgi ve fikirleri kartlara yaz."],["Yerleştir","Her kartı basitten karmaşığa çizgide bir yere koy."],["Açıkla","Neden oraya koydun?"],["Düşün","Bu konuda hangi yeni bakışların ve soruların oldu?"]],"amac":"Konunun farklı yönlerini ve karmaşıklığını düşünerek çok boyutlu bir zihinsel model kurmayı sağlar; asıl değer gerekçededir.","ne":"Konu bir süre işlendikten sonra. Bir kart birden çok yere konabilir; doğru yer değil, akıl yürütme önemli.","id":"karmasiklik-olcegi","ad":"Karmaşıklık Ölçeği","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]},{"tip":"izgara","yon":"yatay","gorsel":true,"adim":[["Görsel 1","Bu konu bu görsele nasıl benziyor? Nasıl benzemiyor?"],["Görsel 2","Bu konu bu görsele nasıl benziyor? Nasıl benzemiyor?"],["Görsel 3","Bu konu bu görsele nasıl benziyor? Nasıl benzemiyor?"],["Görsel 4","Bu konu bu görsele nasıl benziyor? Nasıl benzemiyor?"]],"amac":"Konu ile görseller arasında benzerlik ve farklılık kurarak benzetmeyle düşünmeyi destekler.","ne":"Kutulara dört farklı görsel koyun (köprü, ağaç, düğüm, yol gibi). Önce görsellere sessizce baktırın; çocuklar kendi görsellerini de önerebilir.","id":"gorsellerle-dusunme","ad":"Görsellerle Düşünme","kat":["Sanat, Resim ve Nesneleri Keşfetmek"]}];
